class Point {
  final int _x;
  final int _y;
  final String label;
  int _scale;

  Point({required this._x, required this._y, this.label = 'p', this._scale = 1});

  int get x => this._x;

  int get area => this._x * this._y * this._scale;
}

int run() {
  var a = Point(x: 3, y: 4);
  var b = Point(x: 2, y: 5, scale: 10, label: 'b');
  return a.area + b.area + a.x;
}

String label() {
  var p = Point(x: 1, y: 1);
  return p.label;
}
